gbn(a){return"\u0413\u0440\u0435\u0448\u043a\u0430. \u041c\u043e\u043b\u044f, \u043e\u043f\u0438\u0442\u0430\u0439\u0442\u0435 \u043e\u0442\u043d\u043e\u0432\u043e"},
ge5(){return"\u041f\u043e\u043f\u044a\u043b\u043d\u0435\u0442\u0435 \u0432\u0441\u0438\u0447\u043a\u043e \u043f\u0440\u0435\u0434\u0438 \u0438\u0437\u043f\u0440\u0430\u0449\u0430\u043d\u0435"},
ge0(){return"\u0410\u043a\u043e \u0441\u0442\u0435 \u0441\u043b\u0443\u0436\u0438\u0442\u0435\u043b \u043d\u0430 Edhomy, \u043c\u043e\u043b\u044f, \u0432\u043b\u0435\u0437\u0442\u0435 \u0437\u0430 \u0434\u043e\u0441\u0442\u044a\u043f"},
geL(){return"\u041f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b \u0438 \u043f\u0430\u0440\u043e\u043b\u0430"},
