geJ(){return"\u0422\u0430\u043a, \u0432\u0438 \u043c\u043e\u0436\u0435\u0442\u0435 \u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441 \u0442\u0432\u043e\u0440\u0446\u044f \u044f\u043a \u0432\u0438\u043a\u043b\u0430\u0434\u0430\u0447 \u0430\u0431\u043e \u043f\u0440\u043e\u0444\u0435\u0441\u0456\u043e\u043d\u0430\u043b, \u043c\u0438 \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0438\u043c\u043e \u0432\u0430\u0448 \u0434\u0438\u043f\u043b\u043e\u043c \u0447\u0438 \u0441\u0435\u0440\u0442\u0438\u0444\u0456\u043a\u0430\u0442, \u0456 \u0432\u0438 \u0437\u043c\u043e\u0436\u0435\u0442\u0435 \u043f\u043e\u0447\u0430\u0442\u0438 \u0434\u0456\u043b\u0438\u0442\u0438\u0441\u044f \u043a\u043e\u043d\u0442\u0435\u043d\u0442\u043e\u043c \u0442\u0430 \u0437\u0430\u043b\u0443\u0447\u0430\u0442\u0438 \u043d\u043e\u0432\u0438\u0445 \u043f\u0456\u0434\u043f\u0438\u0441\u043d\u0438\u043a\u0456\u0432. \u042f\u043a\u0449\u043e \u0443 \u0432\u0430\u0441 \u043d\u0435\u043c\u0430\u0454 \u0434\u0438\u043f\u043b\u043e\u043c\u0443 \u0447\u0438 \u0441\u0435\u0440\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u0443, \u0432\u0438 \u043c\u043e\u0436\u0435\u0442\u0435 \u0437\u0430\u0440\u043e\u0431\u043b\u044f\u0442\u0438 \u043b\u0438\u0448\u0435 \u0447\u0435\u0440\u0435\u0437 \u0447\u0430\u0439\u043e\u0432\u0456."},
geD(){return"\u0427\u0438 \u0431\u0435\u0437\u043f\u0435\u0447\u043d\u0430 \u0446\u044f \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430?"},
geC(){return"\u0422\u0430\u043a, \u043c\u0438 \u043d\u0435 \u043f\u0440\u043e\u0434\u0430\u0454\u043c\u043e \u0432\u0430\u0448\u0456 \u0434\u0430\u043d\u0456 \u0442\u0440\u0435\u0442\u0456\u043c \u043e\u0441\u043e\u0431\u0430\u043c. \u0412\u0438 \u043c\u043e\u0436\u0435\u0442\u0435 \u043c\u0430\u0442\u0438 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0438\u0439 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441. \u0412\u0441\u0456 \u0447\u0430\u0442\u0438 \u0441\u0445\u0432\u0430\u043b\u044e\u044e\u0442\u044c\u0441\u044f \u0432\u0430\u043c\u0438 \u043f\u0456\u0441\u043b\u044f \u043f\u0435\u0440\u0448\u043e\u0433\u043e \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f. \u041e\u0431\u0433\u043e\u0432\u043e\u0440\u0435\u043d\u043d\u044f, \u043f\u0430\u0440\u043e\u043b\u0456 \u0442\u0430 \u0431\u0430\u043d\u043a\u0456\u0432\u0441\u044c\u043a\u0430 \u0456\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0456\u044f \u043f\u043e\u0432\u043d\u0456\u0441\u0442\u044e \u0437\u0430\u0448\u0438\u0444\u0440\u043e\u0432\u0430\u043d\u0456. \u041c\u0438 \u0431\u0430\u0447\u0438\u043c\u043e \u0432\u0430\u0448\u0443 \u0456\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0456\u044e \u043b\u0438\u0448\u0435 \u0443 \u0440\u0430\u0437\u0456 \u0441\u043a\u0430\u0440\u0433\u0438 \u0430\u0431\u043e \u044f\u043a\u0449\u043e \u0432\u0438 \u043f\u043e\u0434\u0430\u0454\u0442\u0435 \u0437\u0430\u043f\u0438\u0442 \u043d\u0430 \u0432\u0438\u0432\u0435\u0434\u0435\u043d\u043d\u044f \u043a\u043e\u0448\u0442\u0456\u0432."},
gex(){return"\u042f\u043a \u043d\u0430\u0432\u0447\u0430\u0442\u0438\u0441\u044f \u0432 \u0446\u044c\u043e\u043c\u0443 \u0434\u043e\u0434\u0430\u0442\u043a\u0443?"},
gep(){return"\u041f\u0456\u0434\u043f\u0438\u0441\u0443\u0439\u0442\u0435\u0441\u044c \u043d\u0430 \u0442\u0432\u043e\u0440\u0446\u044f \u0442\u0430 \u0441\u043b\u0456\u0434\u043a\u0443\u0439\u0442\u0435 \u0437\u0430 \u0439\u043e\u0433\u043e \u043a\u0443\u0440\u0441\u0430\u043c\u0438 \u0439 \u0432\u0456\u0434\u0435\u043e\u043a\u043e\u043d\u0444\u0435\u0440\u0435\u043d\u0446\u0456\u044f\u043c\u0438. \u041a\u0443\u0440\u0441\u0438 \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u0456 \u0434\u043b\u044f \u043d\u0430\u0432\u0447\u0430\u043d\u043d\u044f \u0456 \u043c\u043e\u0436\u0443\u0442\u044c \u0432\u043a\u043b\u044e\u0447\u0430\u0442\u0438 \u0432\u0456\u043a\u0442\u043e\u0440\u0438\u043d\u0438, \u0433\u0440\u0430\u0444\u0456\u043a\u0438, \u0441\u043a\u043b\u0430\u0434\u043d\u0456 \u043c\u0430\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u043d\u0456 \u0440\u0456\u0432\u043d\u044f\u043d\u043d\u044f, \u0432\u0456\u0434\u0435\u043e, \u0430\u043d\u0456\u043c\u043e\u0432\u0430\u043d\u0456 \u0456\u0441\u0442\u043e\u0440\u0456\u0457 \u0442\u0430 \u043f\u043e\u0434\u043a\u0430\u0441\u0442\u0438 \u0434\u043b\u044f \u043f\u043b\u0430\u0432\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0444\u0435\u0441\u0456\u0439\u043d\u043e\u0433\u043e \u043d\u0430\u0432\u0447\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0434\u043e\u0441\u0432\u0456\u0434\u0443. \u041a\u043e\u0436\u0435\u043d \u0442\u0432\u043e\u0440\u0435\u0446\u044c \u043c\u043e\u0436\u0435 \u0430\u0434\u0430\u043f\u0442\u0443\u0432\u0430\u0442\u0438 \u0457\u0445 \u043f\u0456\u0434 \u0431\u0443\u0434\u044c-\u044f\u043a\u0443 \u0442\u0435\u043c\u0443. \u0412\u0456\u0434\u0435\u043e\u043a\u043e\u043d\u0444\u0435\u0440\u0435\u043d\u0446\u0456\u0457 \u043f\u043e\u0442\u0440\u0456\u0431\u043d\u0456 \u0434\u043b\u044f \u0437\u0432\u2019\u044f\u0437\u043a\u0443, \u043e\u0446\u0456\u043d\u044e\u0432\u0430\u043d\u043d\u044f \u0442\u0430 \u043d\u0430\u0434\u0430\u043d\u043d\u044f \u0432\u0456\u0434\u0433\u0443\u043a\u0456\u0432."},
